SELECT * FROM stock_history
WHERE stock_code = #{stockCode} AND trade_date = #{tradeDate}
LIMIT 1

SELECT * FROM stock_history
WHERE stock_code = #{stockCode}
ORDER BY trade_date DESC
LIMIT #{limit}

SELECT * FROM stock_history
WHERE stock_code = #{stockCode}
  AND trade_date BETWEEN #{startDate} AND #{endDate}
ORDER BY trade_date ASC
